<?php
require_once dirname(__DIR__,3).'/neptune_secure/bootstrap.php';$u=require_role(['owner','admin']);$org=$u['organization_id'];$msg='';$stats=null;
try{require_once dirname(__DIR__,3).'/neptune_secure/legacy_connection.php';$legacyOk=true;}catch(Throwable $e){$legacyOk=false;$legacyError=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'&&$legacyOk){verify_csrf();$source=in_array($_POST['source']??'',['scouting_submissions','scouting_submissions_hist'],true)?$_POST['source']:'scouting_submissions';$game=(int)$_POST['game_id'];$ownerTeam=!empty($_POST['owner_team_id'])?(int)$_POST['owner_team_id']:null;$eventFilter=trim($_POST['event_filter']??'');$year=(int)$_POST['year'];$q="SELECT * FROM `$source`";$params=[];if($eventFilter!==''){$q.=' WHERE event_name=?';$params[]=$eventFilter;}$q.=' ORDER BY id';$s=$legacyPdo->prepare($q);$s->execute($params);$rows=$s->fetchAll();$inserted=$skipped=0;foreach($rows as $r){$eventName=trim((string)($r['event_name']??'Legacy Event'))?:'Legacy Event';$es=$pdo->prepare('SELECT id FROM events WHERE organization_id=? AND game_id=? AND name=?');$es->execute([$org,$game,$eventName]);$eventId=$es->fetchColumn();if(!$eventId){$pdo->prepare('INSERT INTO events(organization_id,game_id,name,event_code,active) VALUES(?,?,?,?,0)')->execute([$org,$game,$eventName,'legacy']);$eventId=$pdo->lastInsertId();}$mn=max(1,(int)($r['match_no']??1));$ms=$pdo->prepare("SELECT id FROM matches WHERE organization_id=? AND event_id=? AND comp_level='qm' AND match_number=? AND field_id=1");$ms->execute([$org,$eventId,$mn]);$matchId=$ms->fetchColumn();if(!$matchId){$pdo->prepare("INSERT INTO matches(organization_id,event_id,game_id,comp_level,match_number,field_id,state) VALUES(?,?,?,'qm',?,1,'ended')")->execute([$org,$eventId,$game,$mn]);$matchId=$pdo->lastInsertId();}$result=ucfirst(strtolower((string)($r['result']??'Neutral')));if(!in_array($result,['Success','Failure','Neutral'],true))$result='Neutral';$sec=isset($r['time_sec'])?(int)$r['time_sec']:null;$alliance=strtolower((string)($r['alliance']??''))==='blue'?'Blue':'Red';$recorded=!empty($r['timestamp'])?$r['timestamp']:gmdate('Y-m-d H:i:s');try{$iq='INSERT INTO scouting_actions(uuid,organization_id,owner_team_id,event_id,match_id,game_id,frc_team_number,alliance,action_code,location,result,points,match_time_sec,phase,source,source_ip,recorded_at,legacy_source,legacy_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,\'legacy_import\',?,?,?,?)';$pdo->prepare($iq)->execute([uuidv4(),$org,$ownerTeam,$eventId,$matchId,$game,(int)$r['robot'],$alliance,(string)$r['action'],(string)($r['location']??''),$result,(float)($r['points']??0),$sec,phase_for_time($sec),(string)($r['ip_address']??''),$recorded,$source,(int)$r['id']]);$inserted++;}catch(PDOException $e){if($e->getCode()==='23000')$skipped++;else throw $e;}}$stats=['inserted'=>$inserted,'skipped'=>$skipped,'read'=>count($rows)];}
$games=$pdo->query('SELECT id,name,season_year FROM games ORDER BY season_year DESC,name')->fetchAll();$s=$pdo->prepare('SELECT id,frc_team_number,display_name FROM teams WHERE organization_id=? ORDER BY frc_team_number');$s->execute([$org]);$teams=$s->fetchAll();$pageTitle='Legacy Import';include dirname(__DIR__).'/partials_header.php';?>
<h1>Import Stat Owl Data</h1><?php if(!$legacyOk):?><div class="notice">Legacy DB connection is not configured: <?=e($legacyError)?></div><?php else:?><div class="notice">This importer preserves each old row as an individual timestamped scouting action and uses <code>legacy_source + legacy_id</code> to prevent duplicate imports.</div><?php endif;?><?php if($stats):?><div class="card"><b><?=$stats['inserted']?></b> imported · <b><?=$stats['skipped']?></b> already existed · <?=$stats['read']?> read</div><?php endif;?><div class="card" style="margin-top:16px"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Legacy table</label><select name="source"><option>scouting_submissions</option><option>scouting_submissions_hist</option></select><label>Map these records to game</label><select name="game_id"><?php foreach($games as $g):?><option value="<?=$g['id']?>"><?=e($g['season_year'].' '.$g['name'])?></option><?php endforeach;?></select><label>Data owner team (optional)</label><select name="owner_team_id"><option value="">Organization / unknown</option><?php foreach($teams as $t):?><option value="<?=$t['id']?>">#<?=e($t['frc_team_number'].' '.$t['display_name'])?></option><?php endforeach;?></select><label>Only legacy event name (optional; blank imports whole selected table)</label><input name="event_filter"><label>Legacy season/year reference</label><input type="number" name="year" value="2025"><div class="toolbar"><button <?=$legacyOk?'':'disabled'?>>Import</button></div></form></div><?php include dirname(__DIR__).'/partials_footer.php';
